-- Redmi / POCO were originally seeded under Xiaomi. Reassign by name.
-- If the destination brand already has the same model name (from a previous
-- init), merge storage/colors/listings onto that row instead of violating
-- models_brand_id_name_key.
CREATE OR REPLACE FUNCTION telefonak_reassign_phone_models(
    p_from_brand TEXT,
    p_to_brand TEXT,
    p_name_like TEXT
) RETURNS VOID AS $$
DECLARE
    v_from_id INTEGER;
    v_to_id INTEGER;
    v_phone_cat INTEGER;
    v_watch_cat INTEGER;
    r RECORD;
    v_keep_id INTEGER;
    v_drop_id INTEGER;
BEGIN
    SELECT id INTO v_from_id FROM brands WHERE name = p_from_brand;
    SELECT id INTO v_to_id FROM brands WHERE name = p_to_brand;
    SELECT id INTO v_phone_cat FROM categories WHERE slug = 'phones';
    SELECT id INTO v_watch_cat FROM categories WHERE slug = 'smartwatches';
    IF v_from_id IS NULL OR v_to_id IS NULL OR v_phone_cat IS NULL THEN
        RETURN;
    END IF;

    FOR r IN
        SELECT m.id, m.name
        FROM models m
        WHERE m.brand_id = v_from_id
          AND m.name LIKE p_name_like
          AND (v_watch_cat IS NULL OR m.category_id IS DISTINCT FROM v_watch_cat)
    LOOP
        v_keep_id := NULL;
        SELECT m.id INTO v_keep_id
        FROM models m
        WHERE m.brand_id = v_to_id
          AND m.name = r.name
          AND (v_watch_cat IS NULL OR m.category_id IS DISTINCT FROM v_watch_cat);

        IF v_keep_id IS NULL THEN
            UPDATE models
               SET brand_id = v_to_id,
                   category_id = COALESCE(category_id, v_phone_cat)
             WHERE id = r.id;
            CONTINUE;
        END IF;

        IF v_keep_id = r.id THEN
            CONTINUE;
        END IF;

        v_drop_id := r.id;

        INSERT INTO model_storages (model_id, storage_capacity_id, is_active, sort_order)
        SELECT v_keep_id, ms.storage_capacity_id, ms.is_active, ms.sort_order
        FROM model_storages ms
        WHERE ms.model_id = v_drop_id
        ON CONFLICT (model_id, storage_capacity_id) DO UPDATE
            SET is_active = model_storages.is_active OR EXCLUDED.is_active;

        INSERT INTO model_colors (model_id, color_id, official_name, hex_override, is_active, sort_order)
        SELECT v_keep_id, mc.color_id, mc.official_name, mc.hex_override, mc.is_active, mc.sort_order
        FROM model_colors mc
        WHERE mc.model_id = v_drop_id
        ON CONFLICT (model_id, color_id) DO UPDATE
            SET is_active = model_colors.is_active OR EXCLUDED.is_active,
                official_name = COALESCE(model_colors.official_name, EXCLUDED.official_name);

        INSERT INTO model_spec_values (model_id, spec_definition_id, value_text, value_number, value_boolean)
        SELECT v_keep_id, msv.spec_definition_id, msv.value_text, msv.value_number, msv.value_boolean
        FROM model_spec_values msv
        WHERE msv.model_id = v_drop_id
        ON CONFLICT (model_id, spec_definition_id) DO NOTHING;

        UPDATE listings l
           SET model_storage_id = mapped.keep_ms_id,
               model_color_id = mapped.keep_mc_id,
               model_watch_case_size_id = NULL,
               model_watch_connectivity_id = NULL,
               model_id = v_keep_id
          FROM (
            SELECT l2.id AS listing_id,
                   (
                     SELECT ms_keep.id
                     FROM model_storages ms_old
                     JOIN model_storages ms_keep
                       ON ms_keep.model_id = v_keep_id
                      AND ms_keep.storage_capacity_id = ms_old.storage_capacity_id
                     WHERE ms_old.id = l2.model_storage_id
                   ) AS keep_ms_id,
                   (
                     SELECT mc_keep.id
                     FROM model_colors mc_old
                     JOIN model_colors mc_keep
                       ON mc_keep.model_id = v_keep_id
                      AND mc_keep.color_id = mc_old.color_id
                     WHERE mc_old.id = l2.model_color_id
                   ) AS keep_mc_id
            FROM listings l2
            WHERE l2.model_id = v_drop_id
          ) mapped
         WHERE l.id = mapped.listing_id;

        DELETE FROM models WHERE id = v_drop_id;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

SELECT telefonak_reassign_phone_models('Xiaomi', 'Redmi', 'Redmi %');
SELECT telefonak_reassign_phone_models('Xiaomi', 'POCO', 'POCO %');
SELECT telefonak_reassign_phone_models('Xiaomi', 'POCO', 'Poco %');

CREATE OR REPLACE FUNCTION telefonak_seed_phone_model(
    p_brand TEXT,
    p_model TEXT,
    p_year INTEGER,
    p_chipset TEXT,
    p_screen NUMERIC,
    p_storage_gb INT[],
    p_color_specs TEXT[]
) RETURNS VOID AS $$
DECLARE
    v_brand_id INTEGER;
    v_cat_id INTEGER;
    v_model_id INTEGER;
    v_cat_slug TEXT;
    v_gb INTEGER;
    v_spec TEXT;
    v_color_name TEXT;
    v_official TEXT;
    v_ord INTEGER;
    v_keep_storage_ids INTEGER[] := '{}';
    v_color_id INTEGER;
    v_ms_id INTEGER;
BEGIN
    SELECT id INTO v_brand_id FROM brands WHERE name = p_brand;
    IF v_brand_id IS NULL THEN
        RAISE EXCEPTION 'Missing brand: %', p_brand;
    END IF;

    SELECT id INTO v_cat_id FROM categories WHERE slug = 'phones';
    IF v_cat_id IS NULL THEN
        RAISE EXCEPTION 'phones category missing';
    END IF;

    SELECT m.id, c.slug
      INTO v_model_id, v_cat_slug
      FROM models m
      LEFT JOIN categories c ON c.id = m.category_id
     WHERE m.brand_id = v_brand_id
       AND m.name = p_model;

    IF v_cat_slug = 'smartwatches' THEN
        RAISE EXCEPTION 'Refusing to overwrite smartwatch model: % / %', p_brand, p_model;
    END IF;

    IF v_model_id IS NULL THEN
        INSERT INTO models (brand_id, category_id, name, release_year, chipset, screen_size)
        VALUES (v_brand_id, v_cat_id, p_model, p_year, p_chipset, p_screen)
        ON CONFLICT (brand_id, name) DO UPDATE
           SET category_id = COALESCE(EXCLUDED.category_id, models.category_id),
               release_year = COALESCE(EXCLUDED.release_year, models.release_year),
               chipset = COALESCE(EXCLUDED.chipset, models.chipset),
               screen_size = COALESCE(EXCLUDED.screen_size, models.screen_size)
        RETURNING id INTO v_model_id;
    ELSE
        UPDATE models
           SET category_id = v_cat_id,
               release_year = COALESCE(p_year, release_year),
               chipset = COALESCE(p_chipset, chipset),
               screen_size = COALESCE(p_screen, screen_size)
         WHERE id = v_model_id;
    END IF;

    v_ord := 0;
    FOREACH v_gb IN ARRAY COALESCE(p_storage_gb, '{}'::int[]) LOOP
        INSERT INTO model_storages (model_id, storage_capacity_id, is_active, sort_order)
        SELECT v_model_id, sc.id, TRUE, v_ord
        FROM storage_capacities sc
        WHERE sc.capacity_gb = v_gb
        ON CONFLICT (model_id, storage_capacity_id) DO UPDATE
            SET is_active = TRUE, sort_order = EXCLUDED.sort_order;
        SELECT ms.id INTO v_ms_id
        FROM model_storages ms
        JOIN storage_capacities sc ON sc.id = ms.storage_capacity_id
        WHERE ms.model_id = v_model_id
          AND sc.capacity_gb = v_gb;
        v_keep_storage_ids := array_append(v_keep_storage_ids, v_ms_id);
        v_ord := v_ord + 1;
    END LOOP;

    IF array_length(v_keep_storage_ids, 1) IS NOT NULL THEN
        UPDATE model_storages
           SET is_active = FALSE
         WHERE model_id = v_model_id
           AND NOT (id = ANY (v_keep_storage_ids));
    END IF;

    v_ord := 0;
    FOREACH v_spec IN ARRAY COALESCE(p_color_specs, '{}'::text[]) LOOP
        IF position('||' IN v_spec) > 0 THEN
            v_color_name := split_part(v_spec, '||', 1);
            v_official := split_part(v_spec, '||', 2);
        ELSE
            v_color_name := v_spec;
            v_official := v_spec;
        END IF;

        SELECT id INTO v_color_id FROM colors WHERE name = v_color_name;
        IF v_color_id IS NULL THEN
            RAISE EXCEPTION 'Missing color catalog row: %', v_color_name;
        END IF;

        INSERT INTO model_colors (model_id, color_id, official_name, is_active, sort_order)
        VALUES (v_model_id, v_color_id, v_official, TRUE, v_ord)
        ON CONFLICT (model_id, color_id) DO UPDATE
            SET is_active = TRUE,
                official_name = COALESCE(EXCLUDED.official_name, model_colors.official_name),
                sort_order = EXCLUDED.sort_order;
        v_ord := v_ord + 1;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

